        int half = n / 2;

        int sum1 = 0, sum2 = 0;
        int q1 = 0, q2 = 0;

        for (int i = 0; i < half; ++i) {
            if (num[i] == '?') {
                q1++;
            } else {
                sum1 += num[i] - '0';
            }
        }

        for (int i = half; i < n; ++i) {
            if (num[i] == '?') {
                q2++;
            } else {
                sum2 += num[i] - '0';
            }
